Here’s a simple, robust Python function that walks a directory (recursively) and returns a mapping of each file’s path to its SHA-256 hash. It reads files in chunks to handle large files and skips unreadable files gracefully.

```python
import os
import hashlib

def sha256_file(path, chunk_size=1024 * 1024):
    """Compute SHA-256 of a file, reading in chunks."""
    h = hashlib.sha256()
    with open(path, "rb") as f:
        for chunk in iter(lambda: f.read(chunk_size), b""):
            h.update(chunk)
    return h.hexdigest()

def list_file_hashes(root_path, recursive=True):
    """
    List every file under root_path and its SHA-256 hash.

    Returns a dict: {absolute_file_path: sha256_hex or None if unreadable}
    """
    root_path = os.path.abspath(root_path)
    results = {}

    if os.path.isfile(root_path):
        try:
            results[root_path] = sha256_file(root_path)
        except (OSError, PermissionError):
            results[root_path] = None
        return results

    if not os.path.isdir(root_path):
        raise NotADirectoryError(f"Not a file or directory: {root_path}")

    if recursive:
        walker = os.walk(root_path, followlinks=False)
        for dirpath, _, filenames in walker:
            for name in filenames:
                fpath = os.path.join(dirpath, name)
                try:
                    # Skip broken symlinks
                    if not os.path.isfile(fpath):
                        continue
                    results[os.path.abspath(fpath)] = sha256_file(fpath)
                except (OSError, PermissionError):
                    results[os.path.abspath(fpath)] = None
    else:
        for name in os.listdir(root_path):
            fpath = os.path.join(root_path, name)
            try:
                if os.path.isfile(fpath):
                    results[os.path.abspath(fpath)] = sha256_file(fpath)
            except (OSError, PermissionError):
                results[os.path.abspath(fpath)] = None

    return results

